#!/bin/bash
# RTL run of one converted STR2RTS application: UCX-OS application generated by rttools.ucxgen
# from its CSV and .map, injection table at the clock of the flow, Questa simulation with
# experiments/exp23/simulate.sh, analysis of the log against the phase model (rttools.paper.rtlapp,
# rttools.paper.phasecheck), as experiments/car-v-rtl does for CAR-V.
#
#   pilot.sh <APP> <work dir> [<iterations>]
#
# <APP>:        paper name of an application of ../config.json (APP-CFIR, ...)
# <work dir>:   directory outside /home for the copy of the repository, the build and the simulation
#               (hundreds of MB); <work dir>/<name>/{repo,build,sim,results}
# <iterations>: complete iterations after the warm-up that the simulated time covers (default 10):
#               SIM_NS = warm-up 3 ms + (n(v_last) + iterations - 1) T + R_bound + T, rounded up to 0.5 ms
#               (the rule of experiments/car-v-rtl)
#
# The script changes no file of the repository tree it runs from, except its own outputs under
# rtl/<app dir>/ (generated <name>.{c,json,sim}, <name>_tt.h, events.txt, RUN_INFO, time.log,
# metrics.json and the CSV files of the analysis, with the work directory written as <work>). It works
# on a copy of the repository in the work directory: the generated application goes to
# pkt-sim/software/ucx-os/app of the copy, where the UCX-OS Makefile builds every app/str2rts_*.c with
# the rule of the generated applications.
#
# Limits: the generator writes in <name>.sim the limits of the kernel that the application needs above
# the defaults (MAX_TASKS, MAX_PKT_QUEUE_SLOTS) and in <name>_tt.h the entries of the queue of injections
# (NOC_TT_SLOTS, line "Queue:"), and simulate.sh passes them to the build. RAM of a PE:
# the script builds the image with 64 KiB and doubles the RAM until the heap of the image holds the
# demand of the worst PE (rttools.ucxgen memory, 2 packets in flight per input edge between PEs), up
# to 1 MiB; <work dir>/<name>/build.txt records the result. Do not edit this file while a run of it is
# in progress (bash reads the script as it runs).
#
# Clock: the first F_CLK at or above f_search of the flow (../build/apps/<app>.json or
# ../reference.json) whose release period is a whole number of 16-cycle steps of TIMER1 and of cycles.
# The injection table takes the costs of the CSV (RUN_INFO costs=csv).
#
# Environment: ENV_SETUP (as simulate.sh, e.g. "source /usr/share/Modules/init/bash; module load
# riscv64-elf/12.2.0; module load questa/2025.3"), PYTHON (default python3), IMAGE_FLOW=1 (second run,
# after static_costs.py on the image of the first: the clock of the flow with t(v) = max(CSV, static)
# and the handler terms of that image, rtl/<app dir>/static.json, and the injection table with those
# costs, the procedure of the runs of experiments/tt; work in <work dir>/<name>_image, results in
# rtl/<app dir>/image-flow/), RAM_BYTES (power of two: fixes the RAM of each PE instead of the search
# above), STEP=prepare (stop after the generation: no toolchain needed) or STEP=build (stop after the
# build and the heap check: no simulation).
set -euo pipefail

APP=${1:?usage: pilot.sh <APP> <work dir> [<iterations>]}
WORK=${2:?usage: pilot.sh <APP> <work dir> [<iterations>]}
ITER=${3:-10}
PYTHON=${PYTHON:-python3}
HERE=$(cd "$(dirname "$0")" && pwd)
REPO=$(cd "$HERE/../../.." && pwd)
mkdir -p "$WORK"
WORK=$(cd "$WORK" && pwd)
case $WORK in /home/*) echo "work dir must be outside /home: $WORK" >&2; exit 2 ;; esac

# parameters of the run from the conversion and the analysis of the application
eval "$(PYTHONPATH= "$PYTHON" - "$APP" "$ITER" "$REPO" "${IMAGE_FLOW:-0}" "$HERE" <<'EOF'
import json, math, os, sys
from fractions import Fraction
app, iterations, repo = sys.argv[1], int(sys.argv[2]), sys.argv[3]
d = app.lower()
base = os.path.join(repo, "apps", "str2rts", d)
conv = json.load(open(os.path.join(base, "conversion.json")))
row = None
for path, pick in ((os.path.join(repo, "experiments", "str2rts", "build", "apps", d + ".json"), lambda m: m),
                   (os.path.join(repo, "experiments", "str2rts", "reference.json"), lambda m: m["apps"][app])):
    if os.path.exists(path):
        r = pick(json.load(open(path)))["row"]
        if r.get("f_search_hz") and r.get("r_bound_ms"):
            row = r
            break
if sys.argv[4] == "1":
    st = json.load(open(os.path.join(sys.argv[5], d, "static.json")))["flow_image"]
    row = dict(row or {}, f_search_hz=st["f_search_hz"], r_bound_ms=st["r_bound_ms"], phase_last=conv["phase_last"])
if row is None:
    sys.exit("no analysis result of " + app + " (make run)")
T = Fraction(str(conv["period_s"]))
ns = T * 10 ** 9
if ns.denominator != 1:
    sys.exit(f"T = {float(T)} s is not a whole number of ns")
# F_CLK (Hz, whole) with T F_CLK a whole number of 16-cycle steps: F_CLK = 16 m / T, m a multiple of the
# denominator of 16 / T, so the clocks are the multiples of its numerator (32 kHz for T = 0.5 and 1.5 ms)
grid = (Fraction(16) / T).numerator
f_clk = int(math.ceil(row["f_search_hz"] / grid - 1e-9) * grid)
cycles = f_clk * T
assert cycles.denominator == 1 and cycles % 16 == 0 and (f_clk * 3) % 1000 == 0, (f_clk, cycles)
# tick of the kernel: F_TICK = 1 / T when it is whole, otherwise its rounded value and the tick in cycles
f_tick, tick_cycles = (int(1 / T), "") if (1 / T).denominator == 1 else (round(1 / T), int(cycles))
need = Fraction(3, 1000) + (row["phase_last"] + iterations - 1) * T + Fraction(row["r_bound_ms"]) / 1000 + T
sim_ns = int(math.ceil(need * 2000)) * 500000
name = "str2rts_" + "".join(c for c in d.split("-", 1)[1] if c.isalnum())
print(f"DIR={d}; NAME={name}; CSV={conv['files']['csv']}; MAP={conv['files']['map']}; MESH={conv['mesh']}; "
      f"ARCH={conv['arch']}; F_CLK={f_clk}; RELEASE_NS={int(ns)}; SIM_NS={sim_ns}; F_TICK={f_tick}; "
      f"TICK_CYCLES={tick_cycles}; F_SEARCH={row['f_search_hz']}")
EOF
)"
echo "$APP: $NAME, mesh $MESH, F_CLK $F_CLK Hz (f_search $F_SEARCH Hz), T $RELEASE_NS ns, $SIM_NS ns for $ITER iterations"

RUN=$WORK/$NAME
OUT=$HERE/$DIR
COSTS=
if [ "${IMAGE_FLOW:-0}" = 1 ]; then RUN=$WORK/${NAME}_image; COSTS=$OUT/costs_file.json; OUT=$OUT/image-flow; fi
COPY=$RUN/repo
mkdir -p "$RUN"
rsync -a --delete --exclude .git --exclude '/experiments/*/build/' --exclude __pycache__ --exclude '/experiments/str2rts/rtl/app-*/' \
	"$REPO/" "$COPY/"
APPDIR=$COPY/pkt-sim/software/ucx-os/app
SRC=$COPY/apps/str2rts/$DIR
GEN="env PYTHONPATH=$COPY/orca-rt-tools $PYTHON -W ignore -m rttools.ucxgen"
$GEN generate "$SRC/$CSV" "$SRC/$MAP" --name "$NAME" --mesh "$MESH" --out "$APPDIR"
TTCOSTS=
if [ -n "$COSTS" ]; then
	# the analysis of the run looks for the costs file of the table in experiments/wcet/costs/tt of its tree
	cp "$COSTS" "$COPY/experiments/wcet/costs/tt/$NAME.json"
	cp "${COSTS%.json}.handlers.json" "$COPY/experiments/wcet/costs/tt/$NAME.handlers.json"
	TTCOSTS="--costs $COPY/experiments/wcet/costs/tt/$NAME.json"
fi
$GEN tt "$SRC/$CSV" "$SRC/$MAP" --arch "$COPY/arch/$ARCH" --name "$NAME" --clock "$F_CLK" $TTCOSTS --out "$APPDIR"
mkdir -p "$OUT"
cp "$APPDIR/$NAME.c" "$APPDIR/$NAME.json" "$APPDIR/$NAME.sim" "$APPDIR/${NAME}_tt.h" "$OUT/"
[ "${STEP:-}" = prepare ] && exit 0

# build with the limits of <name>.sim; RAM: the first power of two from 64 KiB whose heap holds the demand
limit() { sed -n "s/^$1=\([0-9]*\)\$/\1/p" "$APPDIR/$NAME.sim" | tail -1; }
K_TASKS=$(limit MAX_TASKS)
K_SLOTS=$(limit MAX_PKT_QUEUE_SLOTS)
K_TT=$(sed -n 's/^ \* Queue: NOC_TT_SLOTS \([0-9]*\) .*$/\1/p' "$APPDIR/${NAME}_tt.h" | head -1)
RAM=${RAM_BYTES:-65536}
while :; do
	if APP="$NAME" F_CLK="$F_CLK" F_TICK="$F_TICK" TICK_CYCLES="$TICK_CYCLES" MAX_TASKS="$K_TASKS" \
		MAX_PKT_QUEUE_SLOTS="$K_SLOTS" NOC_TT_SLOTS="$K_TT" RAM_BYTES="$RAM" \
		"$COPY/experiments/exp23/build_sw.sh" "$RUN/build" 2> "$RUN/build_err.txt"; then
		if $GEN memory "$APPDIR/$NAME.json" --image-map "$RUN/build/pkt-sim/software/ucx-os/build/target/image.map" \
			--in-flight 2 --json "$RUN/memory_build.json" > "$RUN/memory_build.txt"; then break; fi
		why="the heap of a PE does not fit"
	elif grep -q "cannot move location counter backwards\|will not fit in region" "$RUN/build/build_sw.log"; then
		# the image alone (code, tables of the tasks, static data) is larger than the RAM
		why="the image does not fit"
	else
		cat "$RUN/build_err.txt" >&2; exit 4
	fi
	if [ -n "${RAM_BYTES:-}" ] || (( RAM >= 1048576 )); then
		echo "$APP: $why in $RAM bytes of RAM" >&2; exit 3
	fi
	echo "$APP: $why in $RAM bytes of RAM; trying $(( RAM * 2 ))"
	RAM=$(( RAM * 2 ))
done
head -1 "$RUN/memory_build.txt"
sed -n '3p' "$RUN/memory_build.txt"
{
	echo "app=$APP name=$NAME mesh=$MESH"
	echo "f_clk_hz=$F_CLK release_ns=$RELEASE_NS sim_ns=$SIM_NS tick_cycles=${TICK_CYCLES:-default}"
	echo "max_tasks=${K_TASKS:-default} max_pkt_queue_slots=${K_SLOTS:-default} noc_tt_slots=${K_TT:-default} ram_bytes=$RAM"
	"$PYTHON" -c "import json, sys; m = json.load(open(sys.argv[1])); r = m['divisors'][0]; \
print('heap=%d demand_worst_pe=%d margin=%d fits=%s' % (m['heap'], r['bytes'], r['margin'], r['fits']))" "$RUN/memory_build.json"
	size "$RUN/build/pkt-sim/software/ucx-os/build/target/image.elf" 2>/dev/null | tail -1 \
		| awk '{ print "image text=" $1 " data=" $2 " bss=" $3 }'
} > "$RUN/build.txt"
cat "$RUN/build.txt"
cp "$RUN/build.txt" "$OUT/build.txt"
[ "${STEP:-}" = build ] && exit 0

SECONDS=0
RAM_BYTES=$RAM F_CLK=$F_CLK RELEASE_NS=$RELEASE_NS \
	"$COPY/experiments/exp23/simulate.sh" "$RUN/sim" "$SIM_NS" "$NAME" "$MESH"
{
	echo "wall_s=$SECONDS"
	# wall time of vsim (time.log of simulate.sh is not stored in the repository: *.log is ignored)
	sed -n 's/.*Elapsed (wall clock) time.*: \(.*\)$/\1/p' "$RUN/sim/time.log" \
		| awk -F: '{ s = 0; for (i = 1; i <= NF; i++) s = s * 60 + $i; printf "vsim_wall_s=%.2f\n", s }'
} > "$RUN/wall.txt"
$GEN memory "$APPDIR/$NAME.json" --image-map "$RUN/sim/pkt-sim/software/ucx-os/build/target/image.map" \
	--in-flight 2 --json "$RUN/memory.json" > /dev/null || echo "$APP: heap check of the image failed" >&2

ANALYZE="env PYTHONPATH=$COPY/orca-rt-tools $PYTHON -W ignore -m"
$ANALYZE rttools.paper.rtlapp analyze "$RUN/sim/events.txt" --manifest "$APPDIR/$NAME.json" --csv "$SRC/$CSV" \
	--map "$SRC/$MAP" --arch "$COPY/arch/$ARCH" --out "$RUN/results"
$ANALYZE rttools.paper.phasecheck "$RUN/results/metrics.json" --rows 5 > "$RUN/results/phasecheck.txt" 2>&1 \
	|| echo "$APP: phasecheck reports phases that do not conform (results/phasecheck.txt)" >&2
cp "$RUN/sim/events.txt" "$RUN/sim/RUN_INFO" "$RUN/sim/time.log" "$RUN/wall.txt" "$RUN/memory.json" "$OUT/"
cp "$RUN/results/"*.json "$RUN/results/"*.csv "$OUT/"
# the copied results name the work directory as <work>
sed "s#$WORK#<work>#g" "$RUN/results/phasecheck.txt" > "$OUT/phasecheck.txt"
echo "$APP: results in $OUT (simulation in $RUN/sim, $SECONDS s)"
